}

// +title=Type versions
// +description=Components and traits pinned to a definition version that no longer exists, which cannot render, or behind the latest
// +chart=pie
// +chart:x=state
// +chart:title=Components and traits by version state
import (
	"list"
	"strings"
	"vela/report"
)

template: {
	parameter: {
		// +usage=Show those on the latest version as well
		// +ui:label=Include those on the latest
		all: *false | bool
	}
	components:  report.#Components
	definitions: report.#Definitions
	defs: {for d in definitions.$returns {"\(d.kind)/\(d.name)": d}}

	all: [for c in components.$returns
		let parts = strings.Split(c.type, "@")
		let def = [if defs["\(c.kind)/\(parts[0])"] != _|_ {defs["\(c.kind)/\(parts[0])"]}, {versions: []}][0]
		let latest = [if def.latest != _|_ {def.latest}, ""][0]
		let pinned = [if len(parts) == 2 {parts[1]}, ""][0] {
			app:       c.app
			component: c.component
			kind:      c.kind
			type:      parts[0]
			"pinned":  [if pinned != "" {pinned}, "-"][0]
			"latest":  [if latest != "" {latest}, "-"][0]
			state: [
				if pinned == "" {"Follows the latest"},
				if !list.Contains(def.versions, pinned) {"Pinned to a missing version"},
				if pinned != latest {"Pinned behind the latest"},
				"Pinned to the latest",
			][0]
		}]

	stats: [
		{label: "Cannot render", value: len([for c in all if c.state == "Pinned to a missing version" {c}]), tone: [if len([for c in all if c.state == "Pinned to a missing version" {c}]) > 0 {"unhealthy"}, "healthy"][0]},
		{label: "Behind the latest", value: len([for c in all if c.state == "Pinned behind the latest" {c}])},
		{label: "Components and traits", value: len(all)},
	]

	rows: [...{
		// +title=Application
		// +link=/applications/{app}/config/components
		app: string
		// +title=Component
		component: string
		// +title=Kind
		kind: string
		// +title=Type
		type: string
		// +title=Pinned
		pinned: string
		// +title=Latest
		latest: string
		// +title=State
		state: string
	}]
	rows: [for c in all if parameter.all || list.Contains(["Pinned to a missing version", "Pinned behind the latest"], c.state) {c}]
}

// +title=Unhealthy applications
// +description=Applications with a component or trait that is not healthy, or a workflow that failed, and why
// +chart=bar
// +chart:x=app
// +chart:group=part
// +chart:title=Unhealthy parts by application
import (
	"list"
	"vela/report"
)

template: {
	applications: report.#List & {$params: {apiVersion: "core.oam.dev/v1beta1", kind: "Application"}}

	apps: [for a in applications.$returns
		let st = [if a.object.status != _|_ {a.object.status}, {}][0] {
			name:      a.object.metadata.name
			namespace: a.namespace
			phase:     [if st.status != _|_ {st.status}, "unknown"][0]
			services:  [if st.services != _|_ {st.services}, []][0]
		}]

	rows: [...{
		// +title=Application
		// +link=/applications/{app}/config
		app: string
		// +title=Part
		part: string
		// +title=Name
		name: string
		// +title=Application phase
		// +format=badge
		phase: string
		// +title=Why
		message: string
	}]
	rows: list.Concat([
		[for a in apps if list.Contains(["workflowFailed", "workflowTerminated"], a.phase) {
			app:     a.name
			part:    "workflow"
			name:    a.name
			phase:   a.phase
			message: "The workflow stopped at \(a.phase)"
		}],
		[for a in apps for s in a.services if !s.healthy {
			app:     a.name
			part:    "component"
			name:    s.name
			phase:   a.phase
			message: [if s.message != _|_ {s.message}, ""][0]
		}],
		[for a in apps for s in a.services if s.traits != _|_ for tr in s.traits if !tr.healthy {
			app:     a.name
			part:    "trait"
			name:    "\(s.name) / \(tr.type)"
			phase:   a.phase
			message: [if tr.message != _|_ {tr.message}, ""][0]
		}],
	])

	unhealthy: {for r in rows {"\(r.app)": true}}
	stats: [
		{label: "Applications", value: len(apps)},
		{label: "Unhealthy", value: len([for k, _ in unhealthy {k}]), tone: [if len(rows) > 0 {"unhealthy"}, "healthy"][0]},
		{label: "Unhealthy parts", value: len(rows)},
	]
}

// +title=Waiting on someone
// +description=Workflows suspended for an approval or input, and how long they have waited
// +chart=bar
// +chart:x=app
// +chart:y=minutes
// +chart:title=Minutes waiting
import (
	"list"
	"vela/report"
)

template: {
	runs: report.#Runs

	rows: [...{
		// +title=Application
		// +link=/applications/{app}/config
		app: string
		// +title=Run
		// +link=/applications/{app}/envbinding/{env}/workflow/records/{run}
		run: string
		// +title=Waiting at
		step: string
		// +title=Waiting for
		// +format=duration
		waited: int
		// +title=Started by
		user: string
		env:     string
		minutes: int
	}]
	rows: list.Sort([for r in runs.$returns if r.status == "suspending"
		let waiting = [for s in *r.steps | [] if s.phase == "suspending" {s}]
		if len(waiting) > 0
		let s = waiting[0] {
			app:     r.app
			run:     r.name
			step:    [if s.alias != _|_ {s.alias}, s.name][0]
			waited:  s.seconds
			user:    [if r.user != _|_ {r.user}, ""][0]
			env:     [if r.env != _|_ {r.env}, ""][0]
			minutes: div(s.seconds, 60)
		}], {x: {}, y: {}, less: x.waited > y.waited})

	stats: [
		{label: "Waiting", value: len(rows), tone: [if len(rows) > 0 {"progressing"}, "healthy"][0]},
		{label: "Longest wait", format: "duration", value: [if len(rows) > 0 {rows[0].waited}, null][0]},
	]
}

// +title=Warning events
// +description=Warnings Kubernetes recorded in the project's namespaces, latest first; Kubernetes keeps events for about an hour
// +chart=bar
// +chart:x=reason
// +chart:y=count
// +chart:title=Warnings by reason
import (
	"list"
	"vela/report"
)

template: {
	events: report.#List & {$params: {apiVersion: "v1", kind: "Event"}}

	rows: [...{
		// +title=Last seen
		// +format=time
		seen: string
		// +title=Reason
		reason: string
		// +title=Object
		object: string
		// +title=Message
		message: string
		// +title=Count
		count: int
		// +title=Namespace
		namespace: string
	}]
	rows: list.Sort([for e in events.$returns if e.object.type == "Warning"
		let o = e.object {
			seen: [
				if (o.lastTimestamp & string) != _|_ {o.lastTimestamp},
				if (o.eventTime & string) != _|_ {o.eventTime},
				o.metadata.creationTimestamp,
			][0]
			reason:    [if o.reason != _|_ {o.reason}, ""][0]
			object:    "\(o.involvedObject.kind)/\(o.involvedObject.name)"
			message:   [if o.message != _|_ {o.message}, ""][0]
			count:     [if o.count != _|_ {o.count}, 1][0]
			namespace: "\(e.cluster)/\(e.namespace)"
		}], {x: {}, y: {}, less: x.seen > y.seen})

	stats: [
		{label: "Warnings", value: list.Sum([for r in rows {r.count}]), tone: [if len(rows) > 0 {"progressing"}, "healthy"][0]},
		{label: "Objects affected", value: len([for k, _ in {for r in rows {"\(r.namespace)/\(r.object)": true}} {k}])},
	]
}
